using System;
using System.Collections;
using System.Linq;
using UnityEngine;
using UnityEngine.SceneManagement;
public sealed class GridShiftMissions:MonoBehaviour {
 GridShiftCompany company;DeliveryManager manager;CompanyCampaignState S=>company.State;public CompanyMission First=>S.missions.FirstOrDefault(m=>m.id=="first-contract");public CompanyMission Selected=>S.missions.FirstOrDefault(m=>m.id==S.selectedMission);
 public void Initialize(){company=GetComponent<GridShiftCompany>();manager=company.Manager;if(S.missions.Count==0){S.missions.Add(new CompanyMission{id="first-contract",type="Principal",name="O Primeiro Contrato",description="Carlos precisa de uma transportadora para seu comércio. Conquiste a confiança dele.",location=company.Balance.merchantPoint,reward=company.Balance.firstMissionBonus,status=CompanyMissionStatus.Active,objectives=new[]{"Abra o tablet com "+GridShiftControls.KeyName(GSAction.Tablet),"Leia a oportunidade na aba Missões","Saia do Office para a cidade","Encontre Carlos no marcador amarelo","Converse com Carlos usando "+GridShiftControls.KeyName(GSAction.Interact),"Aceite a proposta do comerciante","Abra o painel local de operações","Selecione um carro compatível na aba Missões","Inicie a entrega","Acompanhe a frota no mapa ampliado","Aguarde a conclusão da entrega real","Confirme a conclusão no tablet"}});
 Add("expansion","Expansão da GridShift","Contrate um especialista, amplie a frota e conquiste reputação.","Administrativa",70,"Primeiro contrato concluído",new[]{"Conclua três entregas, contrate um especialista, amplie a frota e alcance reputação 32"});Add("crisis","A Crise Logística","A VetorLog disputa os clientes. Mantenha a operação e as contas em ordem.","Principal",90,"Expansão concluída",new[]{"Pague as contas emitidas, faça manutenção e conclua seis entregas com reputação 40"});Add("city-top","O Topo da Cidade","Supere os requisitos do contrato disputado pela VetorLog.","Especial",180,"Crise resolvida e reputação 50",new[]{"Tenha capacidade reforçada e dois veículos livres; aceite a operação especial","Conclua a entrega especial e confirme no painel"});}
 if(!S.missions.Any(m=>m.id=="personal-express")){Add("personal-express","Entrega Expressa","Participe da operação: busque uma encomenda leve e entregue pessoalmente no endereço correto.","Operacional",15,"Entrega pessoal disponível",new[]{"Aceite um contrato com entrega pessoal","Vá ao ponto de coleta e pegue a encomenda","Leve a caixa ao destino e entregue com E","Confirme a conclusão e receba o bônus"});S.missions.Last().status=CompanyMissionStatus.Active;}if(!S.missions.Any(m=>m.id=="neighborhood"))Add("neighborhood","Parceiros do bairro","Uma segunda oportunidade comercial de Carlos para consolidar a parceria.","Secundária",20,"Primeiro contrato concluído",new[]{"Selecione um carro livre e aceite a entrega adicional","Conclua a entrega e confirme o bônus no painel"});if(string.IsNullOrEmpty(S.merchantPoint))S.merchantPoint=company.Balance.merchantPoint;if(string.IsNullOrEmpty(S.deliveryPoint))S.deliveryPoint=company.Balance.deliveryPoint;ValidateRestored();}
 void Add(string id,string name,string desc,string type,float reward,string unlock,string[] objectives){S.missions.Add(new CompanyMission{id=id,name=name,description=desc,type=type,reward=reward,requirement=unlock,objectives=objectives,status=CompanyMissionStatus.Locked,consequence="Sem perda de progresso: reorganize a empresa e tente novamente."});}
 public void TabletOpened(){if(First?.status==CompanyMissionStatus.Active&&First.step==0)Advance(First);}
 public bool ReadOpportunity(out string error){error=null;if(First.step==1){Advance(First);return true;}error="Abra o tablet e selecione a missão inicial.";return false;}
 public void VisitOperations(){if(First?.step==6&&First.status==CompanyMissionStatus.Active)Advance(First);}
 public void MapOpened(){if(First?.step==9&&First.status==CompanyMissionStatus.Active)Advance(First);}
 public bool Talk(bool accept,out string error){error=null;if(First==null||First.status==CompanyMissionStatus.Completed){error="Carlos: obrigado pela parceria. Novos contratos estão no painel.";return false;}if(First.step<3||First.step>5){error="Consulte o objetivo atual no tablet.";return false;}if(First.step==3)Advance(First);if(First.step==4)Advance(First);if(accept&&First.step==5){Advance(First);manager.Notify("Contrato de Carlos aceito. Volte ao painel de operações para escolher o veículo.");}return true;}
 void Advance(CompanyMission m){m.step++;manager.Notify("Objetivo atualizado · "+m.name);company.NotifyChanged();company.Save();}
 public bool StartContract(string vehicleId,out string error){error=null;var mission=First.status==CompanyMissionStatus.Active&&First.step>=7&&First.step<=8?First:S.missions.FirstOrDefault(m=>m.id=="city-top"&&m.status==CompanyMissionStatus.Available);if(mission==null){error="Converse com Carlos e abra as operações antes de iniciar.";return false;}var v=manager.fleet.FirstOrDefault(x=>x!=null&&x.id==vehicleId);float weight=mission==First?5:500;if(v==null||!v.Available||v.capacityKg<weight||(weight<=manager.truckThresholdKg)!=(v.kind==FleetKind.Car)){error="Selecione um veículo livre e compatível com a carga.";return false;}var pickup=manager.Point(S.merchantPoint);var destination=manager.Point(S.deliveryPoint);if(pickup==null||destination==null||DeliveryRouting.Find(v.driver.RotaAtual,pickup.route,DeliveryRouting.Behind(v.driver,pickup))==null){error="O veículo não possui uma rota válida até o cliente.";return false;}if(!manager.TryCreate(new DeliveryRequest{requestId="mission:"+mission.id+(mission==First?"":":"+Guid.NewGuid().ToString("N")),goods=mission==First?"Primeiro contrato de Carlos":"Operação especial GridShift × VetorLog",weightKg=weight,pickupId=pickup.id,destinationId=destination.id,kind=mission==First?DeliveryKind.Local:DeliveryKind.Urgent},out var order,out error))return false;if(order.vehicleId==null&&!v.Assign(order)){error="Veículo indisponível. Atualize e tente novamente.";return false;}mission.orderId=order.id;mission.status=CompanyMissionStatus.Active;mission.step=mission==First?9:1;company.NotifyChanged();company.Save();return true;}
 public bool StartSideContract(string vehicleId,out string error){error=null;var m=S.missions.First(x=>x.id=="neighborhood");var v=manager.fleet.FirstOrDefault(x=>x!=null&&x.id==vehicleId);var pickup=manager.Point(S.merchantPoint);if(m.status!=CompanyMissionStatus.Available||v==null||!v.Available||v.kind!=FleetKind.Car||v.capacityKg<20||pickup==null||DeliveryRouting.Find(v.driver.RotaAtual,pickup.route,DeliveryRouting.Behind(v.driver,pickup))==null){error="Escolha um carro livre com acesso ao cliente; conclua a missão inicial primeiro.";return false;}if(!manager.TryCreate(new DeliveryRequest{requestId="mission:neighborhood",goods="Contrato adicional de Carlos",weightKg=20,kind=DeliveryKind.Local,pickupId=S.merchantPoint,destinationId=S.deliveryPoint},out var order,out error))return false;if(!v.Assign(order)){error="Veículo indisponível.";return false;}m.orderId=order.id;m.step=1;m.status=CompanyMissionStatus.Active;company.NotifyChanged();company.Save();return true;}
 public bool Claim(string id,out string error){error=null;var m=S.missions.FirstOrDefault(x=>x.id==id);if(m==null||m.rewardClaimed||m.status==CompanyMissionStatus.Locked||m.status==CompanyMissionStatus.Available||m.status==CompanyMissionStatus.Failed){error="Recompensa já recebida ou missão inexistente.";return false;}if(m==First){if(!RequirementsMet(m)){error="Acompanhe a frota no mapa e conclua a entrega antes de confirmar.";return false;}}else if(m.id=="city-top"||m.id=="neighborhood"){var o=manager.orders.FirstOrDefault(x=>x.id==m.orderId);if(o==null||!CompletedOrder(m)){error="A operação especial ainda está em andamento.";return false;}if(m.id=="city-top"&&o.elapsedSeconds>o.deadlineSeconds){m.status=CompanyMissionStatus.Failed;company.Reputation(-2);error="Prazo especial excedido. Reorganize a frota e tente outra operação.";company.Save();return false;}}else if(!RequirementsMet(m)){error="Os objetivos desta missão ainda não foram atingidos.";return false;}if(!manager.TryChangeMoney(m.reward,"mission-reward:"+m.id,"Missões",m.name)){error="Recompensa indisponível ou já registrada.";return false;}m.rewardClaimed=true;GridShiftAudio.Play("Mission_Completed","SFX",.55f,2);m.status=CompanyMissionStatus.Completed;if(m.objectives!=null)m.step=m.objectives.Length;company.Reputation(5);manager.Notify("MISSÃO CONCLUÍDA · "+m.name);if(S.selectedMission==m.id)S.selectedMission=null;company.NotifyChanged();if(m==First)manager.Notify("Primeiro contrato concluído! A GridShift acaba de dar seu primeiro passo.");if(m.id=="city-top"){S.complete=true;S.news="GridShift: do zero ao topo. Campanha concluída — continue administrando em modo livre.";}company.Save();return true;}
 public bool Select(string id,out string error){error=null;var m=S.missions.FirstOrDefault(x=>x.id==id&&x.status!=CompanyMissionStatus.Locked&&!x.rewardClaimed);if(m==null){error="Missão bloqueada ou inexistente.";return false;}S.selectedMission=id;company.NotifyChanged();company.Save();return true;}
 public void DeliveryPaid(DeliveryOrder o){var drivers=S.employees.Where(e=>e.hired&&e.role=="Motorista").ToArray();int index=manager.fleet.FindIndex(v=>v!=null&&v.id==o.vehicleId);if(index>=0&&index<drivers.Length)drivers[index].experience=Mathf.Clamp(1+manager.orders.Count(d=>d.vehicleId==o.vehicleId&&d.status==DeliveryStatus.Completed)/5,1,5);company.Reputation(o.deadlineSeconds<=0||o.elapsedSeconds<=o.deadlineSeconds?2:-2);}
 public void Tick(){if(First.status==CompanyMissionStatus.Active){if(First.step==2&&SceneManager.GetActiveScene().name=="SampleScene")Advance(First);if(First.step==10&&manager.orders.Any(o=>o.id==First.orderId&&o.status==DeliveryStatus.Completed))Advance(First);}var side=S.missions.First(m=>m.id=="neighborhood");if(First.rewardClaimed&&side.status==CompanyMissionStatus.Locked){side.status=CompanyMissionStatus.Available;company.NotifyChanged();}int done=manager.orders.Count(o=>o.status==DeliveryStatus.Completed);var expansion=S.missions.First(m=>m.id=="expansion");var crisis=S.missions.First(m=>m.id=="crisis");var top=S.missions.First(m=>m.id=="city-top");if(First.rewardClaimed&&expansion.status==CompanyMissionStatus.Locked){expansion.status=CompanyMissionStatus.Active;S.act=2;GridShiftAudio.Play("Act_Unlocked","SFX",.5f,3);S.selectedMission=expansion.id;company.NotifyChanged();}if(expansion.status==CompanyMissionStatus.Active&&done>=3&&S.employees.Any(e=>e.hired&&e.role!="Motorista")&&manager.Progression.Level("fleet")>0&&S.reputation>=32){expansion.status=CompanyMissionStatus.AwaitingConfirmation;company.Save();company.NotifyChanged();}if(expansion.rewardClaimed&&crisis.status==CompanyMissionStatus.Locked){crisis.status=CompanyMissionStatus.Active;S.act=3;GridShiftAudio.Play("Act_Unlocked","SFX",.5f,3);S.selectedMission=crisis.id;company.Finance.Bill("crisis-inspection","Inspeção logística extraordinária fictícia","Serviços",35,company.Day+4,(int)(company.Day/7)+1);S.news="VetorLog anuncia expansão: mantenha os clientes e reorganize os custos.";company.NotifyChanged();}if(crisis.status==CompanyMissionStatus.Active&&done>=6&&S.reputation>=40&&S.bills.Count>0&&S.bills.All(b=>b.paid)&&S.ledger.Any(t=>t.category=="Manutenção")){crisis.status=CompanyMissionStatus.AwaitingConfirmation;company.Save();company.NotifyChanged();}if(crisis.rewardClaimed&&S.reputation>=50&&manager.Progression.Level("capacity")>0&&manager.fleet.Count(v=>v!=null&&v.Available)>=2&&(top.status==CompanyMissionStatus.Locked||top.status==CompanyMissionStatus.Failed)){top.status=CompanyMissionStatus.Available;S.act=4;GridShiftAudio.Play("Act_Unlocked","SFX",.5f,3);S.selectedMission=top.id;S.news="Contrato disputado: a GridShift pode superar a VetorLog com uma operação urgente bem executada.";company.NotifyChanged();}
 foreach(var candidate in S.missions.Where(m=>!m.rewardClaimed&&(m.status==CompanyMissionStatus.Active||m.status==CompanyMissionStatus.AwaitingConfirmation))){bool met=RequirementsMet(candidate);var target=met?CompanyMissionStatus.AwaitingConfirmation:CompanyMissionStatus.Active;if(candidate.status!=target){candidate.status=target;company.NotifyChanged();company.Save();}}
 if(company.Day>=S.nextEventDay){S.nextEventDay=Math.Floor(company.Day)+1;S.eventOffer=new DeliveryOffer{id="DEMAND-"+Math.Floor(company.Day),goods=S.reputation>=40?"Contrato disputado com a VetorLog":"Demanda adicional do comércio",pickupId=S.merchantPoint,destinationId=S.deliveryPoint,weightKg=S.reputation>=40?500:20,kind=DeliveryKind.Priority};S.eventExpiry=S.nextEventDay;GridShiftAudio.Play("Notification","SFX",.25f,2);var low=S.vehicles.FirstOrDefault(v=>v.condition<30||v.fuel<20);S.news=low!=null?"Revisão operacional necessária: "+low.id+". Abasteça ou programe manutenção na aba Frota.":"Demanda elevada: contratos reais disponíveis na aba Entregas. A VetorLog também busca esses clientes.";company.NotifyChanged();}}
 public bool RequirementsMet(CompanyMission m){if(m==null||m.status==CompanyMissionStatus.Locked||m.status==CompanyMissionStatus.Available||m.status==CompanyMissionStatus.Failed)return false;int done=manager.orders.Count(o=>o.status==DeliveryStatus.Completed);switch(m.id){case "first-contract":return m.step>=11&&CompletedOrder(m);case "personal-express":return manager.orders.Any(o=>o.id==m.orderId&&o.mode==DeliveryMode.Personal&&o.status==DeliveryStatus.Completed);case "expansion":return First.rewardClaimed&&done>=3&&S.employees.Any(e=>e.hired&&e.role!="Motorista")&&manager.Progression.Level("fleet")>0&&S.reputation>=32;case "crisis":return S.missions.First(x=>x.id=="expansion").rewardClaimed&&done>=6&&S.reputation>=40&&S.bills.Count>0&&S.bills.All(b=>b.paid)&&S.ledger.Any(t=>t.category=="Manutenção");case "city-top":case "neighborhood":return CompletedOrder(m);default:return false;}}
 bool CompletedOrder(CompanyMission m)=>!string.IsNullOrEmpty(m.orderId)&&manager.orders.Any(o=>o.id==m.orderId&&o.status==DeliveryStatus.Completed&&o.requestId!=null&&o.requestId.StartsWith("mission:"+m.id));
 void ValidateRestored(){foreach(var m in S.missions){m.step=Mathf.Clamp(m.step,0,m.objectives?.Length??0);if(m.rewardClaimed){m.status=CompanyMissionStatus.Completed;continue;}if(m.status==CompanyMissionStatus.Completed||m.status==CompanyMissionStatus.AwaitingConfirmation)m.status=CompanyMissionStatus.Active;if(m.id=="first-contract"&&m.step>=11&&!CompletedOrder(m))m.step=string.IsNullOrEmpty(m.orderId)?7:10;if((m.id=="neighborhood"||m.id=="city-top")&&m.status==CompanyMissionStatus.Active&&string.IsNullOrEmpty(m.orderId))m.status=CompanyMissionStatus.Available;}if(S.missions.Any(m=>m.id==S.selectedMission&&m.rewardClaimed))S.selectedMission=null;S.version=2;}
 public string StateLabel(CompanyMission m){if(m.rewardClaimed)return "Concluída · Recompensa recebida";switch(m.status){case CompanyMissionStatus.Locked:return "Bloqueada";case CompanyMissionStatus.Available:return "Disponível";case CompanyMissionStatus.Failed:return "Falhou";default:return RequirementsMet(m)?"Objetivos cumpridos — aguardando confirmação":"Em andamento";}}
 public string ProgressText(CompanyMission m){int done=manager.orders.Count(o=>o.status==DeliveryStatus.Completed);switch(m.id){case "expansion":return "Entregas: "+Mathf.Min(done,3)+"/3\nEspecialista contratado: "+(S.employees.Any(e=>e.hired&&e.role!="Motorista")?1:0)+"/1\nUpgrade da frota: "+Mathf.Min(1,manager.Progression.Level("fleet"))+"/1\nReputação: "+S.reputation+"/32";case "crisis":return "Entregas: "+Mathf.Min(done,6)+"/6\nContas pagas: "+S.bills.Count(b=>b.paid)+"/"+S.bills.Count+"\nManutenção realizada: "+(S.ledger.Any(t=>t.category=="Manutenção")?1:0)+"/1\nReputação: "+S.reputation+"/40";case "city-top":case "neighborhood":return "Entrega concluída: "+(CompletedOrder(m)?1:0)+"/1\n"+(m.rewardClaimed?"Recompensa recebida":m.status==CompanyMissionStatus.Available?"Selecione um veículo compatível":string.IsNullOrEmpty(m.orderId)?m.requirement:StateLabel(m));default:int n=m.objectives?.Length??0;int completed=m.rewardClaimed?n:Mathf.Min(m.step,Mathf.Max(0,n-1));return "Objetivos cumpridos: "+completed+"/"+n+"\n"+(m.rewardClaimed?"Missão concluída":n>0?m.objectives[Mathf.Min(m.step,n-1)]:"");}}
 public IEnumerator Introduction(){yield return null;var player=UnityEngine.Object.FindObjectsByType<PlayerMovement>(FindObjectsSortMode.None).FirstOrDefault(p=>p.gameObject.scene.name=="SampleScene");if(player==null)yield break;var ui=GridShiftCampaignUI.Instance;while(ui==null){yield return null;ui=GridShiftCampaignUI.Instance;}ui.ShowIntro();float until=Time.unscaledTime+12;while(!ui.IntroSkipped&&Time.unscaledTime<until)yield return null;ui.Close();if(WorldSession.Instance!=null)yield return WorldSession.Instance.RequestTransition("Office",player.transform);S.introSeen=true;company.Save();manager.Notify("Nova oportunidade comercial disponível! Abra o tablet e leia a aba Missões.");}
}




